<?php $title='Materi';$page='materials';$pdo=Database::connection();$uid=current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$mid=(int)$_POST['module_id'];$check=$pdo->prepare('SELECT id FROM modules WHERE id=? AND teacher_id=?');$check->execute([$mid,$uid]);if(!$check->fetch())exit('Akses modul ditolak');$q=$pdo->prepare('INSERT INTO materials(module_id,title,content,video_url) VALUES(?,?,?,?)');$q->execute([$mid,trim($_POST['title']),trim($_POST['content']),trim($_POST['video_url'])?:null]);flash('success','Materi ditambahkan.');redirect('materials');}$q=$pdo->prepare('SELECT * FROM modules WHERE teacher_id=? ORDER BY title');$q->execute([$uid]);$mods=$q->fetchAll();$q=$pdo->prepare('SELECT ma.*,m.title module_title FROM materials ma JOIN modules m ON m.id=ma.module_id WHERE m.teacher_id=? ORDER BY ma.created_at DESC');$q->execute([$uid]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Materi Pembelajaran</h1><p>Tambahkan materi teks dan tautan video.</p></div></div><section class="panel"><h3>Tambah Materi</h3><form method="post" class="form-grid"><?= csrf_field() ?><label>Modul<select name="module_id" required><?php foreach($mods as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['title']) ?></option><?php endforeach; ?></select></label><label>Judul Materi<input name="title" required></label><label class="full">Konten<textarea name="content" rows="5" placeholder="Tulis materi pembelajaran..."></textarea></label><label class="full">URL Video (opsional)<input type="url" name="video_url" placeholder="https://..."></label><button class="btn btn-primary">Simpan Materi</button></form></section><section class="panel"><h3>Materi yang Diunggah</h3><?php foreach($rows as $r): ?><div class="activity-row"><span class="activity-icon"><i class="fa-solid fa-file-lines"></i></span><div><b><?= e($r['title']) ?></b><small><?= e($r['module_title']) ?></small></div><?php if($r['video_url']): ?><a target="_blank" rel="noopener" href="<?= e($r['video_url']) ?>">Video</a><?php endif; ?></div><?php endforeach; ?></section><?php require __DIR__.'/../_dashboard_end.php'; ?>